import Image from 'next/image'
import Countdown from '@/components/countdown/Countdown'
import ProjectGrid from '@/components/projects/ProjectGrid'
import { sanityFetch } from '@/lib/sanityClient'
import { siteSettingsQuery, projectsQuery } from '@/lib/queries'
import building from '@/assets/building.png' // adjust extension to match your file
import styles from './home.module.css'

export default async function Home() {
  const [settings, projects] = await Promise.all([
    sanityFetch(siteSettingsQuery),
    sanityFetch(projectsQuery),
  ])

  return (
    <>
      <section className={styles.hero}>
        <div className={styles.content}>
          <h1 className={styles.title}>Remember Us</h1>
          <p className={styles.exhibition}>Exhibition ’26</p>
          <p className={styles.tagline}>{settings?.tagline || 'Creative Project Showcase'}</p>
          <Countdown eventDate={settings?.eventDate} eventLocation={settings?.eventLocation} />
        </div>

        <Image
          className={styles.building}
          src={building}
          alt=""
          priority
          sizes="(max-width: 720px) 62vw, 44vw"
        />
      </section>

      <h2>Projects</h2>
      <ProjectGrid projects={projects} />
    </>
  )
}
